1	<script>
2	import CelestialQuoteHistory from "@/components/CelestialQuoteHistory";
3	import GalaxyGeneratorPanel from "./PelleGalaxyGeneratorPanel";
4	import PelleBarPanel from "./PelleBarPanel";
5	import PelleUpgradePanel from "./PelleUpgradePanel";
6	
7	export default {
8	  name: "PelleTab",
9	  components: {
10	    PelleBarPanel,
11	    PelleUpgradePanel,
12	    GalaxyGeneratorPanel,
13	    CelestialQuoteHistory
14	  },
15	  data() {
16	    return {
17	      isDoomed: false,
18	      canEnterPelle: false,
19	      completedRows: 0,
20	      hasStrike: false,
21	      hasGalaxyGenerator: false
22	    };
23	  },
24	  computed: {
25	    symbol() {
26	      return Pelle.symbol;
27	    }
28	  },
29	  methods: {
30	    update() {
31	      this.isDoomed = Pelle.isDoomed;
32	      if (!this.isDoomed) {
33	        this.canEnterPelle = Achievements.prePelle.every(a => a.isUnlocked);
34	        this.completedRows = Achievements.prePelleRows.countWhere(r => r.every(a => a.isUnlocked));
35	      }
36	      this.hasStrike = PelleStrikes.all.some(s => s.hasStrike);
37	      this.hasGalaxyGenerator = PelleRifts.recursion.milestones[2].canBeApplied || GalaxyGenerator.spentGalaxies > 0;
38	    },
39	    toggleBought() {
40	      Pelle.cel.showBought = !Pelle.cel.showBought;
41	      this.$recompute("upgrades");
42	    },
43	    showModal() {
44	      Modal.pelleEffects.show();
45	    },
46	    enterDoomModal() {
47	      Modal.armageddon.show();
48	    }
49	  }
50	};
51	</script>
52	
53	<template>
54	  <div class="l-pelle-celestial-tab">
55	    <div
56	      v-if="isDoomed"
57	      class="l-pelle-all-content-container"
58	    >
59	      <CelestialQuoteHistory celestial="pelle" />
60	      <div class="button-container">
61	        <button
62	          class="o-pelle-button"
63	          @click="showModal"
64	        >
65	          Show effects in Doomed Reality
66	        </button>
67	      </div>
68	      <br>
69	      <GalaxyGeneratorPanel v-if="hasGalaxyGenerator" />
70	      <PelleBarPanel v-if="hasStrike" />
71	      <PelleUpgradePanel />
72	    </div>
73	    <button
74	      v-else-if="canEnterPelle"
75	      class="pelle-doom-button"
76	      @click="enterDoomModal"
77	    >
78	      Doom<br>Your<br>Reality
79	      <div class="pelle-icon-container">
80	        <span class="pelle-icon">{{ symbol }}</span>
81	      </div>
82	    </button>
83	    <div
84	      v-else
85	      class="pelle-unlock-requirements"
86	    >
87	      You need at least 15 rows of achievements before Doomed unlocks.
88	      <br>
89	      {{ completedRows }}/15
90	    </div>
91	  </div>
92	</template>
93	
94	<style scoped>
95	.l-pelle-celestial-tab {
96	  display: flex;
97	  flex-direction: column;
98	  align-items: center;
99	}
100	
101	.l-pelle-all-content-container {
102	  display: flex;
103	  flex-direction: column;
104	  width: 100%;
105	  align-items: center;
106	}
107	
108	.o-pelle-button {
109	  font-family: Typewriter;
110	  color: var(--color-text);
111	  background: var(--color-text-inverted);
112	  border: 0.1rem solid var(--color-pelle--base);
113	  border-radius: var(--var-border-radius, 0.5rem);
114	  margin-bottom: 1rem;
115	  padding: 1rem;
116	  transition-duration: 0.12s;
117	  cursor: pointer;
118	}
119	
120	.o-pelle-button:hover {
121	  box-shadow: 0.1rem 0.1rem 0.3rem var(--color-pelle--base);
122	}
123	
124	.o-pelle-quotes-button {
125	  display: flex;
126	  width: 7rem;
127	  height: 7rem;
128	  justify-content: center;
129	  align-items: center;
130	  font-size: 5rem;
131	  font-weight: 900;
132	  color: var(--color-pelle--base);
133	}
134	
135	.pelle-unlock-requirements {
136	  width: 40rem;
137	  font-size: 3rem;
138	  color: var(--color-pelle--base);
139	  background: black;
140	  border: var(--var-border-width, 0.2rem) solid var(--color-pelle--base);
141	  border-radius: var(--var-border-radius, 0.5rem);
142	}
143	
144	.pelle-doom-button {
145	  width: 20rem;
146	  align-self: center;
147	  font-family: Typewriter;
148	  font-size: 3rem;
149	  color: var(--color-pelle--base);
150	  background: black;
151	  border: var(--var-border-width, 0.2rem) solid var(--color-pelle--base);
152	  border-radius: var(--var-border-radius, 0.5rem);
153	  padding: 1rem;
154	  transition-duration: 0.4s;
155	  cursor: pointer;
156	}
157	
158	.pelle-doom-button:hover {
159	  box-shadow: 0 0 2rem var(--color-pelle--base);
160	}
161	
162	.pelle-icon-container {
163	  display: flex;
164	  width: 15rem;
165	  height: 15rem;
166	  justify-content: center;
167	  align-items: center;
168	  font-size: 10rem;
169	  text-shadow: 0 0 1.5rem #9b0101;
170	  background: white;
171	  border: var(--var-border-width, 0.4rem) solid var(--color-pelle--base);
172	  border-radius: 50%;
173	  box-shadow: 0 0 1.5rem #9b0101;
174	  margin: auto;
175	  margin-top: 3rem;
176	  transition-duration: 0.4s;
177	}
178	
179	.pelle-doom-button:hover .pelle-icon-container {
180	  color: var(--color-pelle--base);
181	  background: black;
182	}
183	
184	@keyframes a-roll {
185	  100% { transform: rotateY(360deg); }
186	}
187	
188	.pelle-icon {
189	  animation: a-roll infinite 8s linear;
190	}
191	
192	.o-celestial-quote-history {
193	  align-self: center;
194	}
195	</style>
